/* ==UserStyle==
@name           Binarium Liquid Glass Framework
@namespace      trader-style
@version        1.0
@match          *://binarium.com/*
@match          *://*.binarium.com/*
==/UserStyle== */

/* ================================================= */
/* ВСЕ ЦВЕТА МЕНЯЮТСЯ ТОЛЬКО ЗДЕСЬ */
/* ================================================= */

:root{

/* ОСНОВНОЙ ФОН */

--bg-main:#0D1117;

/* ФОН ПАНЕЛЕЙ */

--bg-panel:#161B22;

/* ФОН ГРАФИКА */

--bg-chart:#0F172A;

/* ТЕКСТ */

--text-main:#E6EDF3;

/* ВТОРИЧНЫЙ ТЕКСТ */

--text-soft:#9AA4B2;

/* ГРАНИЦЫ */

--border:#2A3441;

/* BUY */

--buy:#35D89C;

/* SELL */

--sell:#FF6076;

/* СВЕЧА ВВЕРХ */

--candle-up:#61F0B8;

/* СВЕЧА ВНИЗ */

--candle-down:#FF7F92;

}

/* ================================================= */
/* ОСНОВА */
/* ================================================= */

html,
body{

background:var(--bg-main)!important;

color:var(--text-main)!important;

font-family:
-apple-system,
BlinkMacSystemFont,
"SF Pro Display",
"Segoe UI",
sans-serif!important;

}

/* ================================================= */
/* ПАНЕЛИ */
/* ================================================= */

header,
nav,
aside,
[class*="panel"],
[class*="container"],
[class*="sidebar"]{

background:var(--bg-panel)!important;

border:1px solid var(--border)!important;

border-radius:18px!important;

}

/* ================================================= */
/* КНОПКИ */
/* ================================================= */

button{

border-radius:14px!important;

transition:.15s ease!important;

}

button:hover{

transform:translateY(-1px);

}

/* ================================================= */
/* BUY */
/* ================================================= */

button[class*="buy"]{

background:var(--buy)!important;

color:white!important;

}

/* ================================================= */
/* SELL */
/* ================================================= */

button[class*="sell"]{

background:var(--sell)!important;

color:white!important;

}

/* ================================================= */
/* INPUT */
/* ================================================= */

input,
select,
textarea{

background:var(--bg-panel)!important;

color:var(--text-main)!important;

border:1px solid var(--border)!important;

}

/* ================================================= */
/* ГРАФИК */
/* ================================================= */

canvas{

filter:none!important;

}

/* ================================================= */
/* СКРОЛЛ */
/* ================================================= */

::-webkit-scrollbar{

width:10px;

}

::-webkit-scrollbar-thumb{

background:var(--border);

border-radius:20px;

}
